import React, { useState } from 'react';
import { MapPin, ChevronRight, ChevronLeft, Search, Box, Globe, Radio } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); 
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  // --- DATA STRUCTURE (Replace with API fetch later) ---
  const zoneData = [
    {
      id: 'Z-1', name: 'NORTH_SECTOR', code: 'NS-ALPHA', 
      theme: '#FF5B03', bg: '#FFB6A9', // Sungold + Petal Pink
      areas: [
        { id: 'A-1', name: 'Hillside Drive', location: 'North Ridge Path', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-2', name: 'University Road', location: 'East Campus Gate', code: 'URD-12', bins: ['BN-502', 'BN-503', 'BN-508'] }
      ]
    },
    {
      id: 'Z-2', name: 'CENTRAL_HUB', code: 'CH-BRAVO', 
      theme: '#47510B', bg: '#CAD23C', // Grassy + Seed Green
      areas: [
        { id: 'A-3', name: 'Main Square', location: 'Downtown Hub', code: 'MSQ-01', bins: ['BN-101', 'BN-102'] }
      ]
    },
    {
      id: 'Z-3', name: 'SOUTH_PORT', code: 'SP-CHARLIE', 
      theme: '#AB1717', bg: '#A1AED1', // Beet Red + Blue Linen
      areas: [
        { id: 'A-4', name: 'Dockside Terminal', location: 'Wharf 7', code: 'W7-DK', bins: ['BN-881', 'BN-889'] }
      ]
    }
  ];

  // --- BACKEND-READY SEARCH LOGIC ---
  const filteredData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()) || z.code.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full h-full flex flex-col gap-6 animate-slot p-2">

      {/* 🟢 TOP NAVIGATION MODULE */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-[#A1AED1] p-5 border-[6px] border-[#47510B] rounded-[45px] shadow-[8px_8px_0_0_#47510B]">
        <div className="flex items-center gap-5">
          {viewLevel !== 'ZONES' && (
            <button 
              onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')} 
              className="w-14 h-14 flex items-center justify-center bg-[#AB1717] text-white rounded-full border-[4px] border-[#47510B] hover:scale-110 active:scale-90 transition-all shadow-lg"
            >
              <ChevronLeft size={28} strokeWidth={4} />
            </button>
          )}
          <div>
            <h2 className="text-3xl font-[1000] text-[#47510B] uppercase italic leading-none tracking-tighter">
              {viewLevel === 'ZONES' ? '02_SECTOR_MAP' : viewLevel === 'AREAS' ? selectedZone.name : selectedArea.name}
            </h2>
            <div className="flex items-center gap-2 mt-1">
              <Radio size={14} className="text-[#AB1717] animate-pulse" />
              <span className="text-[10px] font-black text-[#47510B] opacity-60 uppercase tracking-widest">
                System_Link // {viewLevel}
              </span>
            </div>
          </div>
        </div>

        {/* SEARCH BAR */}
        <div className="relative w-full md:w-96 group">
          <Search className="absolute left-5 top-3.5 text-[#47510B] group-focus-within:scale-125 transition-transform" size={20} />
          <input 
            type="text" 
            placeholder="FILTER_MATRIX..." 
            className="w-full bg-[#FDFAD8] border-[4px] border-[#47510B] rounded-full py-3 pl-14 pr-8 text-xs font-black uppercase outline-none focus:bg-white transition-all shadow-inner"
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* 🟠 MAIN VIEWPORT (AUTO-ADJUSTING SIZE) */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-6">

        {/* LEVEL 1: ZONES */}
        {viewLevel === 'ZONES' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 pb-10 pt-2">
            {filteredData.map(zone => (
              <div 
                key={zone.id} 
                onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
                style={{ backgroundColor: zone.bg }}
                className="group relative p-10 rounded-[65px] cursor-pointer border-[6px] border-[#47510B] shadow-[12px_12px_0_0_#47510B] hover:-translate-y-2 hover:shadow-[18px_18px_0_0_#47510B] transition-all duration-300"
              >
                <div className="flex justify-between items-start mb-14">
                  <div className="bg-white border-[4px] border-[#47510B] p-5 rounded-[30px] shadow-lg group-hover:rotate-6 transition-transform">
                    <Globe size={36} style={{ color: zone.theme }} />
                  </div>
                  <span className="bg-[#47510B] text-[#CAD23C] text-[10px] font-black px-5 py-2 rounded-full uppercase italic border-2 border-white/20">
                    {zone.code}
                  </span>
                </div>
                <h3 className="text-4xl font-[1000] text-[#47510B] tracking-tighter italic leading-none mb-3 uppercase">
                  {zone.name}
                </h3>
                <div className="h-2 w-20 bg-[#47510B]/20 rounded-full mb-4" />
                <p className="text-xs font-black text-[#47510B] uppercase opacity-50">
                  {zone.areas.length} Active_Nodes
                </p>
              </div>
            ))}
          </div>
        )}

        {/* LEVEL 2: AREAS */}
        {viewLevel === 'AREAS' && (
          <div className="flex flex-col gap-6 max-w-6xl mx-auto w-full pb-10 pt-2">
            {filteredData.map(area => (
              <div 
                key={area.id} 
                onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
                className="group flex flex-col md:flex-row items-center bg-white border-[6px] border-[#47510B] p-6 rounded-[55px] hover:bg-[#FFF24D] transition-all cursor-pointer shadow-[10px_10px_0_0_#A1AED1]"
              >
                <div className="w-20 h-20 rounded-[35px] bg-[#CAD23C] border-[4px] border-[#47510B] flex items-center justify-center text-[#47510B] shadow-[5px_5px_0_0_#47510B] group-hover:bg-[#AB1717] group-hover:text-white transition-all">
                  <MapPin size={36} strokeWidth={3} />
                </div>
                <div className="md:ml-10 flex-grow text-center md:text-left mt-6 md:mt-0">
                  <h4 className="text-3xl font-[1000] text-[#47510B] uppercase tracking-tighter italic leading-none mb-2">
                    {area.name}
                  </h4>
                  <div className="flex flex-wrap justify-center md:justify-start gap-4">
                    <span className="text-[10px] font-black text-[#AB1717] bg-[#FFB6A9] px-4 py-1 rounded-full uppercase tracking-widest">
                      {area.location}
                    </span>
                    <span className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-widest px-4 py-1 border-2 border-[#47510B]/10 rounded-full">
                      ID: {area.code}
                    </span>
                  </div>
                </div>
                <div className="mt-6 md:mt-0 px-12 py-4 bg-[#47510B] text-[#CAD23C] rounded-full text-2xl font-black italic shadow-[6px_6px_0_0_#AB1717] group-hover:scale-105 transition-transform">
                  {area.bins.length} UNITS
                </div>
              </div>
            ))}
          </div>
        )}

        {/* LEVEL 3: BINS */}
        {viewLevel === 'BINS' && (
          <div className="flex flex-wrap justify-center gap-10 py-12">
            {selectedArea.bins.map(binId => (
              <div 
                key={binId} 
                className="w-40 h-40 md:w-52 md:h-52 bg-[#FDFAD8] rounded-[65px] border-[6px] border-[#47510B] flex flex-col items-center justify-center gap-3 relative group hover:bg-[#CAD23C] transition-all shadow-[12px_12px_0_0_#47510B] hover:-translate-y-4"
              >
                <div className="absolute -top-3 -right-3 w-16 h-16 bg-[#AB1717] rounded-full flex items-center justify-center border-[5px] border-[#47510B] text-white shadow-xl group-hover:rotate-12 transition-transform">
                  <Box size={28} strokeWidth={3} />
                </div>
                <span className="text-[#47510B] font-[1000] text-3xl tracking-tighter italic">
                  {binId}
                </span>
                <div className="px-4 py-1 bg-[#47510B]/10 rounded-full text-[9px] font-black text-[#47510B] uppercase">
                  Telemetry_On
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 🧭 NAVIGATION FOOTER STATUS */}
      <div className="flex justify-center pb-6">
        <div className="flex items-center gap-6 bg-[#47510B] px-8 py-3 rounded-full shadow-[6px_6px_0_0_#CAD23C] border-4 border-white/10">
          <div className={`w-3 h-3 rounded-full transition-all duration-500 ${viewLevel === 'ZONES' ? 'bg-[#FF5B03] scale-150 shadow-[0_0_12px_#FF5B03]' : 'bg-white/10'}`} />
          <div className={`w-3 h-3 rounded-full transition-all duration-500 ${viewLevel === 'AREAS' ? 'bg-[#CAD23C] scale-150 shadow-[0_0_12px_#CAD23C]' : 'bg-white/10'}`} />
          <div className={`w-3 h-3 rounded-full transition-all duration-500 ${viewLevel === 'BINS' ? 'bg-[#AB1717] scale-150 shadow-[0_0_12px_#AB1717]' : 'bg-white/10'}`} />
        </div>
      </div>

    </div>
  );
};

export default AreasZonesTab;
